//! Replays the golden vectors of `tests/golden` (generated by `GoldenVectorGenerator` from the C# persistence stack,
//! see `tests/golden/README.md`) through the Rust stack built the same way: the layout persistence, then
//! [`CachedReaderPersistence`], then optionally [`CarryForwardCachingPersistence`]. Every column must match the C# dump
//! byte for byte after each write step, and every read must return what C# returned.
//!
//! Runs on the in-memory and the managed backends, and with the `rocksdb-it` feature on real RocksDB.

mod common;

use std::path::{Path, PathBuf};

use common::any_kv::{AnyKv, Backend};
use common::{column_entries, column_name, hex, hex20, hex32, to_hex};
use flatdb_core::codec::metadata::SLOT_ENCODING_KEY;
use flatdb_core::kv::{Column, KvStore, ReadFlags, WriteFlags};
use flatdb_core::persistence::cached_reader::CachedReaderPersistence;
use flatdb_core::persistence::carry_forward::CarryForwardCachingPersistence;
use flatdb_core::persistence::layouts::KvPersistence;
use flatdb_core::persistence::{FlatIterator, Persistence, PersistenceReader, PersistenceWriteBatch, ReaderFlags};
use flatdb_core::types::{Account, FlatLayout, StateId, TreePath, U256};
use serde_json::Value;

type Result<T> = std::result::Result<T, String>;

fn golden_files() -> Vec<PathBuf> {
    let directory = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden");
    let mut files: Vec<PathBuf> = std::fs::read_dir(&directory)
        .map(|entries| {
            entries
                .filter_map(|entry| entry.ok().map(|entry| entry.path()))
                .filter(|path| path.extension().is_some_and(|extension| extension == "json"))
                .collect()
        })
        .unwrap_or_default();
    files.sort();
    files
}

fn replay_all(backend: Backend) {
    let files = golden_files();
    if files.is_empty() {
        eprintln!("notice: no golden vectors in tests/golden yet; generate them with GoldenVectorTests");
        return;
    }

    let mut failures = Vec::new();
    let mut replayed = 0;
    for file in &files {
        let Some(store) = backend.open() else {
            eprintln!("skipped: the {backend:?} backend is unavailable");
            return;
        };
        let text = std::fs::read_to_string(file).unwrap();
        let vector: Value = serde_json::from_str(&text).unwrap_or_else(|error| panic!("{}: {error}", file.display()));
        if let Err(error) = replay(&store.kv, &vector) {
            failures.push(format!("{}: {error}", file.file_name().unwrap().to_string_lossy()));
        }
        replayed += 1;
    }

    assert!(
        failures.is_empty(),
        "{} of {replayed} vectors diverge on {backend:?}:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn golden_vectors_replay_on_the_mem_backend() {
    replay_all(Backend::Mem);
}

#[test]
fn golden_vectors_replay_on_the_managed_backend() {
    replay_all(Backend::Managed);
}

#[cfg(feature = "rocksdb-it")]
#[test]
fn golden_vectors_replay_on_rocksdb() {
    replay_all(Backend::Rocks);
}

fn replay(kv: &AnyKv, vector: &Value) -> Result<()> {
    let layout = match str_field(vector, "layout")? {
        "Flat" => FlatLayout::Flat,
        "FlatInTrie" => FlatLayout::FlatInTrie,
        "PreimageFlatV1" => FlatLayout::PreimageFlatV1,
        "PreimageFlat" => FlatLayout::PreimageFlat,
        other => return Err(format!("unknown layout {other}")),
    };
    let slot_encoding = match str_field(vector, "slotEncoding")? {
        "rlp" => 1,
        "raw" => 0,
        other => return Err(format!("unknown slot encoding {other}")),
    };

    // The C# side forces the slot encoding before the persistence resolves it.
    let mut batch = kv.write_batch().map_err(|error| error.to_string())?;
    batch
        .put(
            Column::Metadata,
            &*SLOT_ENCODING_KEY,
            &[slot_encoding],
            WriteFlags::NONE,
        )
        .map_err(|error| error.to_string())?;
    batch.commit().map_err(|error| error.to_string())?;

    let persistence = KvPersistence::new(kv.clone(), layout, None).map_err(|error| error.to_string())?;
    let cached = CachedReaderPersistence::new(persistence).map_err(|error| error.to_string())?;
    let steps = field(vector, "steps")?.as_array().ok_or("steps is not an array")?;
    if field(vector, "carryForward")?
        .as_bool()
        .ok_or("carryForward is not a bool")?
    {
        let carry_forward = CarryForwardCachingPersistence::new(cached).map_err(|error| error.to_string())?;
        replay_steps(kv, &carry_forward, steps)
    } else {
        replay_steps(kv, &cached, steps)
    }
}

fn replay_steps<P: Persistence>(kv: &AnyKv, persistence: &P, steps: &[Value]) -> Result<()> {
    for (index, step) in steps.iter().enumerate() {
        let kind = str_field(step, "kind")?;
        let outcome = match kind {
            "batch" => replay_batch(persistence, step).and_then(|()| check_columns(kv, step)),
            "read" => replay_read(persistence, step),
            "flush" => persistence.flush().map_err(|error| error.to_string()),
            "clear" => persistence
                .clear()
                .map_err(|error| error.to_string())
                .and_then(|()| check_columns(kv, step)),
            other => Err(format!("unknown step kind {other}")),
        };
        outcome.map_err(|error| format!("step {index} ({kind}): {error}"))?;
    }
    Ok(())
}

fn replay_batch<P: Persistence>(persistence: &P, step: &Value) -> Result<()> {
    let flags = WriteFlags::from_bits(u64_field(step, "writeFlags")? as u32);
    let mut batch = persistence
        .create_write_batch(&state_id(field(step, "from")?)?, &state_id(field(step, "to")?)?, flags)
        .map_err(|error| error.to_string())?;

    for (index, op) in field(step, "ops")?
        .as_array()
        .ok_or("ops is not an array")?
        .iter()
        .enumerate()
    {
        let name = str_field(op, "op")?;
        apply(&mut batch, name, op).map_err(|error| format!("op {index} ({name}): {error}"))?;
    }
    batch.commit().map_err(|error| error.to_string())
}

fn apply(batch: &mut impl PersistenceWriteBatch, name: &str, op: &Value) -> Result<()> {
    let result = match name {
        "selfDestruct" => batch.self_destruct(&hex20(str_field(op, "address")?)),
        "setAccount" => batch.set_account(
            &hex20(str_field(op, "address")?),
            account(field(op, "account")?)?.as_ref(),
        ),
        "setStorage" => {
            let value = field(op, "value")?;
            let value = (!value.is_null()).then(|| u256_32(value)).transpose()?;
            batch.set_storage(
                &hex20(str_field(op, "address")?),
                &u256_32(field(op, "slot")?)?,
                value.as_ref(),
            )
        }
        "setStateTrieNode" => batch.set_state_trie_node(&path(field(op, "path")?)?, &hex(str_field(op, "rlp")?)),
        "setStorageTrieNode" => batch.set_storage_trie_node(
            &hex32(str_field(op, "addressHash")?),
            &path(field(op, "path")?)?,
            &hex(str_field(op, "rlp")?),
        ),
        "setStorageRawEncoded" => batch.set_storage_raw_encoded(
            &hex32(str_field(op, "addressHash")?),
            &hex32(str_field(op, "slotHash")?),
            &hex(str_field(op, "rlpValue")?),
        ),
        "setAccountRaw" => batch.set_account_raw(
            &hex32(str_field(op, "addressHash")?),
            &account(field(op, "account")?)?.ok_or("a raw account is never null")?,
        ),
        "deleteAccountRange" => {
            batch.delete_account_range(&hex32(str_field(op, "from")?), &hex32(str_field(op, "to")?))
        }
        "deleteStorageRange" => batch.delete_storage_range(
            &hex32(str_field(op, "addressHash")?),
            &hex32(str_field(op, "from")?),
            &hex32(str_field(op, "to")?),
        ),
        "deleteStateTrieNodeRange" => {
            batch.delete_state_trie_node_range(&hex32(str_field(op, "from")?), &hex32(str_field(op, "to")?))
        }
        "deleteStorageTrieNodeRange" => batch.delete_storage_trie_node_range(
            &hex32(str_field(op, "addressHash")?),
            &hex32(str_field(op, "from")?),
            &hex32(str_field(op, "to")?),
        ),
        other => return Err(format!("unknown op {other}")),
    };
    result.map_err(|error| error.to_string())
}

fn replay_read<P: Persistence>(persistence: &P, step: &Value) -> Result<()> {
    let flags = ReaderFlags::from_bits(u64_field(step, "readerFlags")? as u32);
    let reader = persistence.create_reader(flags).map_err(|error| error.to_string())?;
    for (index, read) in field(step, "expect")?
        .as_array()
        .ok_or("expect is not an array")?
        .iter()
        .enumerate()
    {
        let name = str_field(read, "op")?;
        let expected = field(read, "result")?;
        let actual = run_read(&reader, name, read).map_err(|error| format!("read {index} ({name}): {error}"))?;
        if actual != *expected {
            return Err(format!("read {index} ({name}) {read}: got {actual}"));
        }
    }
    Ok(())
}

/// Runs a read and renders its result as the generator records it.
fn run_read(reader: &impl PersistenceReader, name: &str, read: &Value) -> Result<Value> {
    let flags = |read: &Value| -> Result<ReadFlags> { Ok(ReadFlags::from_bits(u64_field(read, "readFlags")? as u32)) };
    let bytes = |value: Option<Vec<u8>>| value.map_or(Value::Null, |value| Value::String(to_hex(&value)));
    let found = |value: Option<U256>| serde_json::json!({ "found": value.is_some(), "value": to_hex(&value.unwrap_or_default().to_be_bytes()) });
    let error = |error: flatdb_core::persistence::PersistenceError| error.to_string();

    Ok(match name {
        "currentState" => {
            let state = reader.current_state();
            serde_json::json!({ "block": state.block_number, "root": to_hex(&state.state_root) })
        }
        "isPreimageMode" => Value::Bool(reader.is_preimage_mode()),
        "getAccount" => account_json(reader.get_account(&hex20(str_field(read, "address")?)).map_err(error)?),
        "tryGetSlot" => found(
            reader
                .try_get_slot(&hex20(str_field(read, "address")?), &u256_32(field(read, "slot")?)?)
                .map_err(error)?,
        ),
        "tryLoadStateRlp" => bytes(
            reader
                .try_load_state_rlp(&path(field(read, "path")?)?, flags(read)?)
                .map_err(error)?,
        ),
        "tryLoadStorageRlp" => bytes(
            reader
                .try_load_storage_rlp(
                    &hex32(str_field(read, "addressHash")?),
                    &path(field(read, "path")?)?,
                    flags(read)?,
                )
                .map_err(error)?,
        ),
        "getAccountRaw" => bytes(
            reader
                .get_account_raw(&hex32(str_field(read, "addressHash")?))
                .map_err(error)?,
        ),
        "tryGetStorageRaw" => found(
            reader
                .try_get_storage_raw(
                    &hex32(str_field(read, "addressHash")?),
                    &hex32(str_field(read, "slotHash")?),
                )
                .map_err(error)?,
        ),
        "accountIterator" => drain(
            reader
                .create_account_iterator(&hex32(str_field(read, "start")?), &hex32(str_field(read, "end")?))
                .map_err(error)?,
        )?,
        "storageIterator" => drain(
            reader
                .create_storage_iterator(
                    &hex32(str_field(read, "accountKey")?),
                    &hex32(str_field(read, "start")?),
                    &hex32(str_field(read, "end")?),
                )
                .map_err(error)?,
        )?,
        other => return Err(format!("unknown read {other}")),
    })
}

fn drain(mut iterator: impl FlatIterator) -> Result<Value> {
    let mut entries = Vec::new();
    while iterator.move_next().map_err(|error| error.to_string())? {
        entries.push(serde_json::json!([
            to_hex(&iterator.current_key()),
            to_hex(iterator.current_value())
        ]));
    }
    Ok(Value::Array(entries))
}

fn check_columns(kv: &AnyKv, step: &Value) -> Result<()> {
    let columns = field(step, "columns")?;
    for column in Column::ALL {
        let expected: Vec<(Vec<u8>, Vec<u8>)> = match columns.get(column_name(column)) {
            None => Vec::new(),
            Some(entries) => entries
                .as_array()
                .ok_or("a column dump is not an array")?
                .iter()
                .map(|entry| (hex(entry[0].as_str().unwrap()), hex(entry[1].as_str().unwrap())))
                .collect(),
        };
        let actual = column_entries(kv, column);
        if actual != expected {
            return Err(column_difference(column, &expected, &actual));
        }
    }
    Ok(())
}

/// The first entry where a column dump differs.
fn column_difference(column: Column, expected: &[(Vec<u8>, Vec<u8>)], actual: &[(Vec<u8>, Vec<u8>)]) -> String {
    let render = |entry: Option<&(Vec<u8>, Vec<u8>)>| {
        entry.map_or("nothing".to_owned(), |(key, value)| {
            format!("{} => {}", to_hex(key), to_hex(value))
        })
    };
    let index = expected
        .iter()
        .zip(actual)
        .position(|(expected, actual)| expected != actual)
        .unwrap_or(expected.len().min(actual.len()));
    format!(
        "column {} has {} entries, expected {}; first difference at {index}: expected {}, got {}",
        column_name(column),
        actual.len(),
        expected.len(),
        render(expected.get(index)),
        render(actual.get(index))
    )
}

fn field<'a>(value: &'a Value, name: &str) -> Result<&'a Value> {
    value.get(name).ok_or_else(|| format!("missing {name} in {value}"))
}

fn str_field<'a>(value: &'a Value, name: &str) -> Result<&'a str> {
    field(value, name)?
        .as_str()
        .ok_or_else(|| format!("{name} is not a string"))
}

fn u64_field(value: &Value, name: &str) -> Result<u64> {
    field(value, name)?
        .as_u64()
        .ok_or_else(|| format!("{name} is not an unsigned integer"))
}

fn state_id(value: &Value) -> Result<StateId> {
    Ok(StateId::new(
        u64_field(value, "block")?,
        hex32(str_field(value, "root")?),
    ))
}

fn path(value: &Value) -> Result<TreePath> {
    let length = u64_field(value, "length")?;
    if length > 64 {
        return Err(format!("path length {length}"));
    }
    Ok(TreePath::new(hex32(str_field(value, "path")?), length as u8))
}

fn u256_32(value: &Value) -> Result<U256> {
    Ok(U256::from_be_bytes(&hex32(
        value.as_str().ok_or("a 32-byte value is not a string")?,
    )))
}

/// A nonce or balance: big-endian bytes without leading zeros.
fn quantity(value: &Value) -> Result<U256> {
    let bytes = hex(value.as_str().ok_or("a quantity is not a string")?);
    if bytes.len() > 32 {
        return Err(format!("quantity of {} bytes", bytes.len()));
    }
    Ok(U256::from_be_slice(&bytes))
}

fn account(value: &Value) -> Result<Option<Account>> {
    if value.is_null() {
        return Ok(None);
    }

    let nonce = quantity(field(value, "nonce")?)?;
    if !nonce.is_u64() {
        return Err("nonce over 64 bits".to_owned());
    }
    Ok(Some(Account::with_hashes(
        nonce.0[0],
        quantity(field(value, "balance")?)?,
        hex32(str_field(value, "storageRoot")?),
        hex32(str_field(value, "codeHash")?),
    )))
}

fn account_json(account: Option<Account>) -> Value {
    let quantity = |value: U256| {
        let (bytes, start) = value.to_minimal_be();
        to_hex(&bytes[start..])
    };
    account.map_or(Value::Null, |account| {
        serde_json::json!({
            "nonce": quantity(U256::from_u64(account.nonce)),
            "balance": quantity(account.balance),
            "storageRoot": to_hex(&account.storage_root),
            "codeHash": to_hex(&account.code_hash),
        })
    })
}
